# Own-wording magic items of Valda's Spire of Secrets (2014 rules), Adamantine Polish to Gauntlet of the Grandmaster.
ITEMS = []; SP = {}; WPN = {}; GEAR = []
def add(name, typ, rar, att, text, **o):
    ITEMS.append((name, typ, rar, att, text, o))

add("Adamantine Polish", "Potion", "Uncommon", 0, "An abrasive paste you apply as an action to a creature's claws, fangs, tusks or spines. For 8 hours that creature gets +1 to attack and damage rolls with its natural weapons, and they count as adamantine for overcoming resistance and immunity.")
add("Alchemical Anesthetic", "Potion", "Uncommon", 0, "A syringe holding 4 doses of a clear, odorless drug. As an action, give a dose to a willing creature: for 1 hour it feels no pain, has Advantage on Constitution checks and saves, and cannot be incapacitated or given Disadvantage by pain. It does not notice its own injuries or exhaustion, so the GM tracks a player character's hit points and exhaustion meanwhile. Giving a dose over 1 minute to a willing or unconscious creature knocks it out for 1 hour. One more dose every 8 hours keeps it out for up to 24 hours. Keeping it out longer kills it.")
add("Alchemical Reactor", "Wondrous Item", "Very Rare", 1, "A cask-sized machine of valves and dials. Attuned, use an action to set it to brew one of: potion of flying, potion of hill giant strength, potion of invisibility, potion of superior healing, 1 ounce of sovereign glue, or universal solvent. It runs for 12 hours, then you pour out the potion with an action. The potion turns nonmagical if not used within 24 hours. You also regain 2 expended reagent dice after each Short Rest.", by="Alchemist")
add("Ankh of Anubis", "Wondrous Item", "Rare", 1, "A wrought iron holy symbol. While you have 10 hit points or fewer, you have Advantage on attack rolls, ability checks and saving throws. Track all damage you take in a pool that resets at the end of your turn. When you lose hit points to cast a Martyr spell, subtract the pool from the hit point cost (minimum 0).", by="Martyr")
add("Antimagic Bell", "Wondrous Item", "Common", 0, "A round bell enchanted to stay silent. It rings only when its magic is disrupted, for example inside an antimagic field.")
add("Aqua Fortis", "Potion", "Rare", 0, "A bubbling transparent acid in a sealed vial. As an action, throw it up to 20 ft with a ranged attack as an improvised weapon. Against an unattended object it dissolves a 1-ft cube. On armor or a shield it gives a permanent, cumulative -1 to AC (armor at AC 10 or a shield at +0 is destroyed). On a weapon it gives a permanent, cumulative -1 to damage (at -5 it is destroyed). It does nothing to magic items or to gold, glass, stone and adamantine. A creature takes 3d6 Acid, then 2d6 at the end of its next turn, then 1d6 at the end of the turn after. A gallon of water washes it off and ends the effect.")
add("Arrow of Explosions", "Weapon", "Very Rare", 0, "A trick arrow. When it strikes a creature, object or surface it bursts in fire. Each creature within 20 ft makes a DC 17 Dexterity save, taking 8d6 Fire on a failure or half on a success. The arrow is destroyed.")
add("Arrow of Glue", "Weapon", "Uncommon", 0, "A trick arrow whose shaft turns soft on impact and then hardens. Fire it at any point you can see in range to cover a 1-ft square with hardened glue (the GM may give Disadvantage on hard shots). A creature it hits makes a DC 15 Dexterity save or is stuck to a nearby surface and cannot move. It breaks free with a DC 15 Strength (Athletics) check.")
add("Arrow of Piercing", "Weapon", "Rare", 0, "A trick arrow. When you attack with it, it becomes a 5-ft-wide line of magical energy from you to the weapon's normal range. Each creature in the line makes a DC 15 Dexterity save, taking the weapon's normal damage on a failure or half on a success. The arrow is then destroyed.")
add("Arrow of Teleportation", "Weapon", "Uncommon", 0, "A trick arrow. Fired from a bow at an empty space within 100 ft of you, it teleports you to that space. The arrow is destroyed on impact.")
add("Aura Lenses", "Wondrous Item", "Rare", 0, "A cylindrical case of eight tinted glass lenses, each 4 inches across and tied to a school of magic: Abjuration white, Conjuration blue, Divination yellow, Enchantment pink, Evocation red, Illusion purple, Necromancy grey, Transmutation green. Looking through a lens tints the world its color, except creatures and objects under a spell of that school, which stay uncolored. A full set is Rare. A set missing lenses (1d8 found) is Uncommon.")
add("Bag of Cheer", "Wondrous Item", "Legendary", 0, "A 30-lb red velvet sack that seems full of wrapped gifts. As an action, pull out a present and give it to another creature. It suits the recipient and is worth up to 100 gp (the GM picks or rolls: weapon or shield, gold, art object, clothing, tool or instrument, potion of healing, gems, exotic food, book, toy or game). After three presents the bag stops working until the next dawn, and any further gifts are empty boxes.")
add("Bedroll of Rest", "Wondrous Item", "Rare", 1, "A silk bedroll of great comfort. A Long Rest in it removes all levels of exhaustion and restores all expended Hit Dice. After sleeping in it you need no rest for 48 hours, though you can still take a Long Rest in that time.")
add("Bells of Due Alarm", "Wondrous Item", "Uncommon", 0, "Three bells that guard against intruders. Place them up to 500 ft apart, then use an action and a command word to cast alarm over the area between them.")
add("Blindfold of True Darkness", "Wondrous Item", "Rare", 1, "You have blindsight to 10 ft, which lets you see anything not behind cover, including invisible creatures that fail to hide from you. Curse. Attuning curses you until remove curse or similar magic ends it. While cursed you are blinded, whether or not you wear the blindfold.")
add("Boots of the Hare", "Wondrous Item", "Rare", 1, "When you take the Dash action in them, you gain 90 ft of extra movement instead of the normal amount. Curse. It shows only through identify or on attunement. Attuning curses you until remove curse or similar magic ends it. While cursed your speed is 15 ft and nothing raises it except the Dash action.")
add("Boots of the Trail", "Wondrous Item", "Uncommon", 0, "Until worn they look ruined. Once laced they become fine hiking boots with gold clasps and silk laces. You leave no tracks or traces and cannot be tracked except by magic. You can march twice as long before gaining exhaustion. You can also take them off and speak a command word as an action: they walk off on their own, leaving a false trail up to 1 mile in any direction, then teleport back to your feet.")
add("Bonze's Bokken", "Weapon", "Rare", 1, "A Katana-style weapon that deals Bludgeoning instead of Slashing. As an action, blow a strong wind that disperses gas in an adjacent 15-ft cube. When you take the Attack action with it, you can replace one or more attacks with a ranged spell attack of sonic waves, range 30/60 ft, +7 to hit. On a hit it deals 1d10 + 3 Thunder and, on a critical hit, deafens the target. The sound can be heard out to 100 ft.", base=["Katana"])
add("Brawling Gloves (uncommon)", "Wondrous Item", "Uncommon", 1, "Fingerless magic gloves. You are proficient with all improvised weapons and gain +1 to attack and damage rolls made with them.", by="Barbarian, Captain, Craftsman, Fighter, Rogue or Warden")
add("Brawling Gloves (rare)", "Wondrous Item", "Rare", 1, "Fingerless magic gloves. You are proficient with all improvised weapons and gain +2 to attack and damage rolls made with them.", by="Barbarian, Captain, Craftsman, Fighter, Rogue or Warden")
add("Brawling Gloves (very rare)", "Wondrous Item", "Very Rare", 1, "Fingerless magic gloves. You are proficient with all improvised weapons and gain +3 to attack and damage rolls made with them.", by="Barbarian, Captain, Craftsman, Fighter, Rogue or Warden")
add("Burning Knuckles", "Weapon", "Rare", 1, "Magic gauntlets. Your unarmed strikes deal 2d6 Fire damage instead of their usual damage.", base=["Cestus"])
add("Cane of Youth", "Wondrous Item", "Uncommon", 1, "While attuned you feel none of the frailty of old age and cannot be aged by magic. You can still die of old age.")
add("Chameleon Concoction", "Potion", "Uncommon", 0, "Your skin matches the color and texture of your surroundings for 1 hour, giving you Advantage on Dexterity (Stealth) checks to avoid being seen. The liquid shifts hue to match whatever it is near.")
add("Coil of Strength Storing", "Wondrous Item", "Uncommon", 1, "A metal coil worn on an arm or leg. Each time a melee weapon attack beats a hostile creature's AC by 5 or more, the coil stores 1 charge (max 5). When you make a melee weapon attack, spend any number of stored charges for a bonus to the attack roll equal to the number spent. Decide after the d20 roll but before the GM says hit or miss. Stored charges vanish 1 minute after being stored.")
add("Cure-All", "Potion", "Uncommon", 0, "Holds 1d4 + 1 doses of strong medicine, with a red swirl shaped like a snake on a staff. As an action, drink a dose to cure any disease, end the Poisoned condition and become immune to it for 1 hour. Shaking the bottle does not mix the swirl.")
add("Dowsing Rod", "Wondrous Item", "Uncommon", 0, "A forked stick for finding water. It has 3 charges and regains 1d3 at dawn. Holding it, use an action and 1 charge to make it point to the largest water source within 10 miles. It gives no distance or amount. With little water around it points vaguely downward.", ch=[3, "1d3", "dawn"])
add("Drum of Blasted Beats", "Wondrous Item", "Rare", 1, "A drum with 6 charges that regains 1d6 at dusk. Strike it as an action and spend 1 charge to cast thunderwave, or 2 charges to cast shatter (save DC 15). If you spend the last charge, roll a d20. On a 1 the drum ruptures and loses its magic.", ch=[6, "1d6", "dusk"])
SP["Drum of Blasted Beats"] = {"sp": [["Thunderwave", 1], ["Shatter", 2]]}
add("Flutterby Rod", "Rod", "Uncommon", 0, "A rod with 7 charges that regains 1d6 + 1 at dawn. Holding it, cast light on the rod at will. As an action, spend 1 charge to fire a green butterfly-shaped bolt at a target within 60 ft (ranged spell attack, +5). On a hit it deals 1d4 + 1 Force and outlines the target in glowing butterflies. The next attack roll against it before the end of your next turn has Advantage, and until then it cannot benefit from being invisible.", ch=[7, "1d6+1", "dawn"])
add("Folding Ladder", "Wondrous Item", "Uncommon", 0, "Two 12-inch wooden rods joined side by side, weighing 4 lb, with three command words. The first unfolds a ladder 2 ft wide and 20 ft long. The second makes a freestanding stepladder 30 ft high on a 5 by 10 ft base. The third folds it back. Either form holds 500 lb.")
add("Frog Prince Statuette", "Wondrous Item", "Rare", 0, "A clay statuette of a frog in a crown. Speak its command word and kiss it as an action to turn it into a humanoid with the commoner statistics from the spell Mandy's feral follower. It speaks your languages, wears fine clothes and keeps its memories across transformations. It lasts until the twelfth stroke of midnight (24 hours where time does not pass normally), then reverts. It also reverts at 0 hit points or if you speak the command word while touching it. After use it cannot transform again for 5 days.")
add("Gambler's Coin", "Wondrous Item", "Rare", 1, "A plain gold piece with deep scratches on one face. It has 3 charges and regains all at dawn. When you make an ability check, attack roll or saving throw while holding it, spend 1 charge to replace the d20 roll with a coin flip. Heads counts as a 20 (no critical hit and no other effect that needs a natural 20). Tails counts as a 1.", ch=[3, "all", "dawn"])
add("Gaol Net", "Weapon", "Rare", 1, "A magic Net. When it restrains a Large or smaller creature, use a Bonus Action and its command word to turn it into a Large iron cage around the target, which is no longer restrained. The cage weighs 500 lb and has a locked door (DC 15 to pick). A creature, including the prisoner, can use an action for a DC 25 Strength check to bend the bars enough to free it. Use an action and the command word to turn an empty cage back into a net. After it becomes a cage it cannot do so again until the next dawn.", base=["Net"])
for _r, _b in (("Uncommon", 1), ("Rare", 2), ("Very Rare", 3)):
    add("Gauntlet of the Grandmaster (%s)" % _r.lower(), "Wondrous Item", _r, 1, "A gauntlet that serves as a spellcasting focus for your Warmage spells. You gain +%d to spell attack rolls, spell damage rolls and the save DCs of your Warmage spells. It counts as a specially prepared gauntlet for cantrips such as force buckler. You also gain one of force buckler, force dart or force weapon, which does not count against your cantrips known. You can change the choice after each Long Rest." % _b, by="Warmage")
